struct SquareRoot : public Worker {
  tbb::enumerable_thread_specific<bool> printme;
  const RVector<double> input;
  RVector<double> output;
  SquareRoot(const NumericVector input, NumericVector output) 
    : printme(false), input(input), output(output) {}
  
  void operator()(std::size_t begin, std::size_t end) {
    tbb::enumerable_thread_specific<bool>::reference printme_local = printme.local();
    if(!printme_local) { // print once per thread
      std::cout << "T";
      printme_local = true;
    }
    std::transform(input.begin() + begin, 
                   input.begin() + end, 
                   output.begin() + begin, 
                   ::sqrt);
  }
};

// [[Rcpp::export(rng = false)]]
NumericVector psqrt2(NumericVector x, int nthreads) {
  NumericVector output(Rf_xlength(x));
  SquareRoot squareRoot(x, output);
  parallelFor2(0, Rf_xlength(x), squareRoot, 1, nthreads);
  std::cout << std::endl;
  return output;
}
```

